import sys

def place_knights(n):
    knights = []
    x, y = 0, 0
    dx, dy = 0, 1
    step = 1
    while len(knights) < n:
        for _ in range(2):
            for _ in range(step):
                if len(knights) < n:
                    knights.append((x, y))
                    x += dx
                    y += dy
            dx, dy = -dy, dx
        step += 1
    return knights

def main():
    n = int(sys.stdin.readline().strip())
    knights = place_knights(n)
    for knight in knights:
        print(knight[0], knight[1])

if __name__ == "__main__":
    main()
